INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','present-continuous','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"present-continuous","title":"Present continuous","level":"A1","order":13,"summary":"Describe actions happening now with the right form of be and an -ing form.","learningGoals":["Actions in progress","Building the verb","Questions and negatives"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Actions in progress","explanation":"Use am, is or are plus an -ing form for an activity in progress now. The form of be agrees with the subject.","examples":["The dog is sleeping by the fire.","We are discussing the route."]},{"title":"Building the verb","explanation":"Many verbs add -ing. Usually remove a final silent e; some short verbs double their last consonant. Learn spelling with the verb.","examples":["write → writing","cut → cutting"]},{"title":"Questions and negatives","explanation":"Move be before the subject in a question. Put not after be in a negative. Keep the -ing form in both.","examples":["Are they loading the van?","I am not using the lift."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-continuous","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"6f2357f8-2f8a-5c3b-ad66-0ebdc3ca9508","topicSlug":"present-continuous","level":"A1","prompt":"Right now, I ____ dinner in the kitchen. Use the present continuous.","choices":[{"id":"A","text":"is cooking"},{"id":"B","text":"are cooking"},{"id":"C","text":"am cook"},{"id":"D","text":"am cooking"}],"answerId":"D","hint":"Use am, is or are plus an -ing form for an activity in progress now. The form of be agrees with the subject. Focus on **affirmative** in this question.","explanation":"The present continuous needs am plus cooking with “I”.","keywords":[],"source":"seed","skill":"affirmative","contextKey":"verb-cook","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-continuous","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"9f93e453f95fde5f9fbb5ff3851cca103a6446a165debc1bbf2c3b8fdaf7b2ee","teaching":{"steps":["Identify what the question tests: **affirmative**. Use am, is or are plus an -ing form for an activity in progress now. The form of be agrees with the subject.","The present continuous needs am plus cooking with “I”.","Choose **am cooking**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"**is** does not match the subject’s person/number or the construction’s tense here. The present continuous needs am plus cooking with “I”.","B":"**are** does not match the subject’s person/number or the construction’s tense here. The present continuous needs am plus cooking with “I”.","C":"The auxiliary is in the right family, but the rest of **am cook** does not complete the required verb pattern. The present continuous needs am plus cooking with “I”.","D":"The present continuous needs am plus cooking with “I”."}}},{"id":"d0c899a2-5992-5028-ab55-ae24ff154dd8","topicSlug":"present-continuous","level":"A1","prompt":"Complete the present-continuous negative: I ____ dinner in the kitchen right now.","choices":[{"id":"A","text":"am not cooking"},{"id":"B","text":"is not cooking"},{"id":"C","text":"are not cooking"},{"id":"D","text":"do not cooking"}],"answerId":"A","hint":"Move be before the subject in a question. Put not after be in a negative. Keep the -ing form in both. Focus on **negative** in this question.","explanation":"Keep the -ing form and put not after am: I am not cooking.","keywords":[],"source":"seed","skill":"negative","contextKey":"verb-cook","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-continuous","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"83d5085707706c113d8fa24455b722f33f044b1b7a6c6785d1777614e8709a65","teaching":{"steps":["Identify what the question tests: **negative**. Move be before the subject in a question. Put not after be in a negative. Keep the -ing form in both.","Keep the -ing form and put not after am: I am not cooking.","Choose **am not cooking**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"Keep the -ing form and put not after am: I am not cooking.","B":"**is** does not match the subject’s person/number or the construction’s tense here. Keep the -ing form and put not after am: I am not cooking.","C":"**are** does not match the subject’s person/number or the construction’s tense here. Keep the -ing form and put not after am: I am not cooking.","D":"This construction uses its existing **am** form, so **do not cooking** introduces the wrong auxiliary. Keep the -ing form and put not after am: I am not cooking."}}},{"id":"ebb20084-4fb1-5d6c-ad8f-7970b31d81f6","topicSlug":"present-continuous","level":"A1","prompt":"____ I cooking dinner in the kitchen right now?","choices":[{"id":"A","text":"Is"},{"id":"B","text":"Are"},{"id":"C","text":"Does"},{"id":"D","text":"Am"}],"answerId":"D","hint":"Move be before the subject in a question. Put not after be in a negative. Keep the -ing form in both. Focus on **question** in this question.","explanation":"Move am before “I” to make this present-continuous 